add('mse-gradients',['02-02'],'Average a regression gradient','Return the gradient with respect to w of mean squared error for y_hat=w*x+b. x and y have equal nonzero sizes.','double mse_dw(const std::vector<double>& x, const std::vector<double>& y, double w, double b)','Sum 2*residual*x and divide by the example count.\n    return 0.0;','    double g=0;\n    for(std::size_t i=0;i<x.size();++i) g+=2*(w*x[i]+b-y[i])*x[i];\n    return g/x.size();',[
 ('Worked initial gradient','near(mse_dw({1,2},{3,5},0,0),-13)','The two residual-weighted terms sum to -26 and average to -13.'),('Exact fit','near(mse_dw({1,2},{3,5},2,1),0)','An exact linear fit has zero residuals.'),('Repeated data invariant','near(mse_dw({1,2,1,2},{3,5,3,5},0,0),-13)','A mean objective is invariant to duplicating every example.'),('Bias included','near(mse_dw({2},{5},1,1),-8)','The prediction includes b before forming the residual.')],['For one example the derivative is 2*(prediction-target)*x.','Divide by N once, outside the loop.'],'The duplicated-data fixture catches a missing mean reduction.','Implement the bias derivative and verify both with finite differences.')
