add('bpe-merge',['05-04'],'Perform one non-overlapping BPE merge','Replace every left-to-right adjacent pair (a,b) with merged. Do one pass; newly merged IDs are not reconsidered.','std::vector<int> merge_pair(const std::vector<int>& ids, int a, int b, int merged)','Consume two IDs on a match, otherwise one.\n    return {};','    std::vector<int> out;\n    for(std::size_t i=0;i<ids.size();){\n        if(i+1<ids.size() && ids[i]==a && ids[i+1]==b){out.push_back(merged);i+=2;}\n        else out.push_back(ids[i++]);\n    }\n    return out;',[
 ('Repeated pair','merge_pair({1,2,1,2},1,2,9)==std::vector<int>({9,9})','Both non-overlapping occurrences merge.'),('Overlapping candidates','merge_pair({1,1,1},1,1,9)==std::vector<int>({9,1})','The middle ID cannot belong to two merges.'),('Unmatched end','merge_pair({1,2,1},1,2,9)==std::vector<int>({9,1})','Do not access past the final ID.'),('Empty input','merge_pair({},1,2,9).empty()','The pass must terminate on empty text.')],['Use a while-style loop with an explicit index increment.','On a match advance by 2.'],'Learning pair rankings and applying ranked merges are separate parts of a full BPE tokenizer.','Implement pair-frequency counting and a reversible merge vocabulary.')
add('causal-weights',['06-01','06-02'],'Mask before normalizing attention','Given one row of finite attention scores, return a probability vector of the same length with positions >query equal to zero. query is a valid zero-based index.','std::vector<double> causal_weights(const std::vector<double>& scores, int query)','Find max and sum only over visible positions.\n    return {};','    double m=scores[0];\n    for(int j=0;j<=query;++j)m=std::max(m,scores[j]);\n    std::vector<double> out(scores.size(),0);double sum=0;\n    for(int j=0;j<=query;++j){out[j]=std::exp(scores[j]-m);sum+=out[j];}\n    for(int j=0;j<=query;++j)out[j]/=sum;\n    return out;',[
 ('First token sees itself','vector_near(causal_weights({0,100,100},0),{1,0,0})','Future scores cannot influence the visible distribution.'),('Uniform visible prefix','vector_near(causal_weights({0,0,999},1),{.5,.5,0})','Masked scores are excluded from the denominator.'),('Stable large scores','vector_near(causal_weights({1000,1001,9999},1),{.26894142137,.73105857863,0})','Subtract the maximum over only visible scores.'),('Last position','vector_near(causal_weights({0,0,0},2),{1.0/3,1.0/3,1.0/3})','The last query may see all three keys.')],['Never let a future score enter max or sum.','Initialize all outputs to zero, then fill the visible prefix.'],'Masking after a full softmax without renormalization is not equivalent to causal attention.','Multiply the resulting row by scalar values and test future-value invariance.')
add('rope-rotation',['06-03'],'Rotate a query pair','Return a 2D rotation of (x,y) by theta radians. This is the paired-coordinate arithmetic used inside RoPE.','std::vector<double> rotate_pair(double x, double y, double theta)','Apply the 2×2 rotation matrix.\n    return {};','    const double c=std::cos(theta),s=std::sin(theta);\n    return {x*c-y*s,x*s+y*c};',[
 ('Quarter turn','vector_near(rotate_pair(1,0,1.5707963267948966),{0,1})','The positive x axis rotates onto positive y.'),('Zero angle','vector_near(rotate_pair(3,4,0),{3,4})','Identity rotation preserves coordinates.'),('Negative angle','vector_near(rotate_pair(0,1,-1.5707963267948966),{1,0})','The sine term must keep its sign.'),('Half turn','vector_near(rotate_pair(2,-3,3.141592653589793),{-2,3})','A half turn flips both coordinates.')],['Use radians, not degrees.','The x output has a minus sine term; y has a plus sine term.'],'Full RoPE selects an angle for every position and coordinate pair, then rotates both queries and keys.','Apply a rotation and its inverse, and numerically test norm preservation.')
add('rms-normalization',['06-04'],'Normalize by root mean square','Return x/sqrt(mean(x²)+epsilon). Input is nonempty, epsilon>0, and learned gains are omitted in this small fixture.','std::vector<double> rms_norm(const std::vector<double>& x, double epsilon)','Compute mean square, not variance.\n    return {};','    double sum=0;for(double v:x)sum+=v*v;\n    const double denom=std::sqrt(sum/x.size()+epsilon);\n    auto out=x;for(double& v:out)v/=denom;\n    return out;',[
 ('Two features','vector_near(rms_norm({3,4},1e-8),{.848528137084,1.131370849445})','The denominator uses (9+16)/2.'),('Zero input','vector_near(rms_norm({0,0},1e-5),{0,0})','Epsilon keeps zero inputs finite.'),('Signed features','vector_near(rms_norm({-2,2},1e-8),{-1,1})','Normalization preserves signs.'),('Constant vector','vector_near(rms_norm({2,2},1e-8),{1,1})','RMSNorm does not subtract the mean.')],['RMS is not the standard deviation.','Add epsilon inside the square root.'],'The constant-vector test distinguishes RMSNorm from centered LayerNorm.','Add learned channel gains and gradient-check a small vector.')
add('dispatch-size',['07-01','07-02','07-03'],'Cover a GPU dispatch safely','Return ceiling(n/threads_per_group) for n≥0, group size>0. The final group may contain padding threads, so a real kernel still needs tid<n.','int threadgroups(int n, int threads_per_group)','Count full groups plus a partial final group.\n    return 0;','    return n/threads_per_group+(n%threads_per_group!=0);',[
 ('Boundary padding','threadgroups(257,64)==5','Four groups cover only 256 elements.'),('Exact division','threadgroups(256,64)==4','Do not create an unnecessary group.'),('Single element','threadgroups(1,64)==1','One element still needs a group.'),('No elements','threadgroups(0,64)==0','The host can skip an empty dispatch.')],['Integer division truncates.','Ceiling group count does not remove the kernel bounds check.'],'This CPU drill checks launch arithmetic only. A browser WASI program cannot execute Metal kernels.','Use this result in your local Metal host and compare n=257 with CPU output.')
add('error-tolerance',['07-04','07-05','11-02'],'Compare CPU and GPU results honestly','Return true if |a-b| ≤ atol+rtol*|reference|. Use b as the reference. Both tolerances are nonnegative and inputs are finite.','bool close_enough(double a, double b, double atol, double rtol)','Combine absolute and reference-relative tolerances.\n    return false;','    return std::abs(a-b)<=atol+rtol*std::abs(b);',[
 ('Near zero','close_enough(1e-8,0,1e-7,1e-5)','Absolute tolerance matters near zero.'),('Large magnitude','close_enough(1000.5,1000,1e-6,.001)','A small relative discrepancy can be acceptable.'),('Wrong result','!close_enough(2,1,1e-6,1e-5)','Tolerance must not accept arbitrary errors.'),('Negative reference','close_enough(-100.01,-100,1e-8,.001)','Reference magnitude needs abs.')],['Subtract the two outputs before taking abs.','The relative term uses absolute reference magnitude.'],'Passing tolerances is a numerical agreement claim, not a performance claim. Choose tolerances appropriate to dtype and operation.','Report maximum absolute error and relative error on nonsquare CPU/GPU fixtures.')
add('clip-global-norm',['08-02'],'Clip a global gradient norm','Return g scaled to have norm at most limit. If g has zero norm, return it unchanged. Assume limit>0.','std::vector<double> clip_norm(const std::vector<double>& g, double limit)','Compute the whole vector norm and one shared scale.\n    return {};','    double sum=0;for(double v:g)sum+=v*v;\n    const double norm=std::sqrt(sum);\n    const double scale=norm>limit?limit/norm:1;\n    auto out=g;for(double& v:out)v*=scale;\n    return out;',[
 ('3-4-5 vector','vector_near(clip_norm({3,4},1),{.6,.8})','Global clipping preserves direction.'),('Already small','vector_near(clip_norm({.1,.2},1),{.1,.2})','Do not enlarge a small gradient.'),('Zero norm','vector_near(clip_norm({0,0},1),{0,0})','Avoid dividing by zero.'),('Negative direction','vector_near(clip_norm({-3,-4},2),{-1.2,-1.6})','The shared scale is positive.')],['Compute sqrt(sum(g_i²)).','Clip the norm, not individual coordinates.'],'This is global norm clipping; it differs from componentwise clipping. Apply before the optimizer update.','Extend your local AdamW loop and record unclipped and clipped norms.')
add('attention-memory',['08-04'],'Account for quadratic attention storage','Return bytes for a materialized float32 score tensor [B,H,T,T]. Inputs are small nonnegative values; compute in double to avoid intermediate integer overflow.','double score_bytes(double B, double H, double T)','Multiply all axes and four bytes per entry.\n    return 0.0;','    return B*H*T*T*4.0;',[
 ('Small score tensor','near(score_bytes(1,2,8),512)','1×2×8×8×4=512.'),('Context doubled','near(score_bytes(1,2,16),2048)','Doubling T quadruples the score storage.'),('Batch scales linearly','near(score_bytes(2,2,8),1024)','The batch axis appears once.'),('Empty context','near(score_bytes(1,2,0),0)','Zero positions produce no scores.')],['T appears twice.','Weights and KV-cache bytes are separate allocations.'],'Efficient attention can avoid storing this full tensor; the formula is for the naive materialized implementation.','Compare measured memory with this estimate and list additional allocations.')
add('chat-template',['09-01','09-02','11-04'],'Serialize a toy conversation boundary','Our explicitly toy format is <user>MESSAGE</user><assistant>. Return that exact sequence. Assume message contains no reserved markers. Real models require their own actual templates.','std::string toy_chat(const std::string& message)','Include both the closing user marker and assistant start marker.\n    return "";','    return "<user>"+message+"</user><assistant>";',[
 ('Simple message','toy_chat("hello")=="<user>hello</user><assistant>"','The assistant generation boundary must be present.'),('Preserve whitespace','toy_chat("a b")=="<user>a b</user><assistant>"','Do not silently retokenize the message.'),('Empty message','toy_chat("")=="<user></user><assistant>"','An empty message still has structural boundaries.')],['This is string serialization, not an inference call.','The example format is a teaching contract, not a universal chat template.'],'Correct template serialization preserves role and generation boundaries. This fixture does not emulate a trained assistant.','Render the actual template of your selected local model and compare token IDs.')
add('rank-one-lora',['09-03'],'Apply a low-rank weight update','For a rank-one update ΔW=B A with B shaped [M,1] and A [1,N], return row-major ΔW. This is a simple outer product.','std::vector<double> rank_one(const std::vector<double>& B, const std::vector<double>& A)','Multiply each B row value by each A column value.\n    return {};','    std::vector<double> out;\n    for(double b:B)for(double a:A)out.push_back(b*a);\n    return out;',[
 ('Rectangular outer product','vector_near(rank_one({1,2},{3,4,5}),{3,4,5,6,8,10})','The output keeps M and N, reducing the rank axis.'),('Negative update','vector_near(rank_one({-1},{2,-3}),{-2,3})','Adapter updates are signed.'),('Zero factor','vector_near(rank_one({0,0},{7}),{0,0})','A zero factor produces zero update.')],['The rank axis has one element, so there is no visible inner sum.','General rank r adds a sum over r.'],'Ordinary LoRA learns small factors while base weights remain frozen. A complete adapter includes scaling and selected target layers.','Add general rank r and compare parameter counts with a dense update.')
add('heldout-accuracy',['09-04','09-05','11-03'],'Score correctness, not fluency','Return the fraction of exactly matching predicted and expected rule IDs. Equal nonempty lengths are guaranteed. Return a floating-point fraction.','double accuracy(const std::vector<int>& predictions, const std::vector<int>& expected)','Count matches, then divide as double.\n    return 0.0;','    int correct=0;\n    for(std::size_t i=0;i<expected.size();++i)if(predictions[i]==expected[i])++correct;\n    return static_cast<double>(correct)/expected.size();',[
 ('Partial correctness','near(accuracy({1,2,0,4},{1,2,3,4}),.75)','Three of four labels match.'),('No correct outputs','near(accuracy({0,0},{1,2}),0)','Plausible-looking wrong labels still fail.'),('All correct','near(accuracy({1,2},{1,2}),1)','Report a fraction from zero to one.'),('Avoid integer division','near(accuracy({1,0,0},{1,2,3}),1.0/3)','The numerator must convert before division.')],['Count exact matches on frozen held-out tasks.','Integer division truncates partial accuracy to zero.'],'This fixture checks exact-match accounting only. Real rules also need syntax, domain, and semantic validation.','Report per-category raw counts and compare all baselines on the same held-out cases.')
add('rule-boundary',['10-01','10-02'],'Interpret an exact threshold rule','Our rule language supports >=, >, and ==. Return whether x satisfies op threshold. Unknown operators must return false.','bool accepts(double x, const std::string& op, double threshold)','Implement the three operators and reject everything else.\n    return false;','    if(op==">=")return x>=threshold;\n    if(op==">")return x>threshold;\n    if(op=="==")return x==threshold;\n    return false;',[
 ('Inclusive boundary','accepts(18,">=",18)','At least 18 includes exactly 18.'),('Strict boundary','!accepts(18,">",18)','Over 18 excludes exactly 18.'),('Above boundary','accepts(19,">",18)','Strict inequality accepts a higher value.'),('Equality','accepts(7,"==",7)','Equality is part of the declared vocabulary.'),('Unknown operator','!accepts(20,"approximately",18)','Unsupported semantics must not be invented.')],['Test the exact boundary, not only points far away.','An unknown operator must have an explicit failure behavior.'],'A model-generated rule only becomes usable when its semantics are interpreted and tested precisely.','Generate boundary triplets threshold-1, threshold, threshold+1 for every numeric rule.')
add('retry-policy',['10-04'],'Bound verifier-guided retries','Return the zero-based index of the first valid proposal among at most budget proposals, or -1 if none is valid. budget≥0.','int first_valid(const std::vector<int>& valid, int budget)','Stop at both the budget and the available proposals.\n    return 0;','    for(int i=0;i<budget && i<static_cast<int>(valid.size());++i)if(valid[i])return i;\n    return -1;',[
 ('Accept second proposal','first_valid({0,1,1},3)==1','Return the first valid candidate.'),('Budget exhaustion','first_valid({0,0,1},2)==-1','A later valid candidate is outside the budget.'),('No attempts','first_valid({1},0)==-1','Zero budget cannot accept a proposal.'),('No proposals','first_valid({},3)==-1','Do not read beyond the available candidates.')],['Use both loop bounds.','Failure must be explicit, not the final invalid proposal.'],'A retry loop is only as sound as its verifier. This policy controls cost and makes failure observable.','Add rejection reasons and include retry cost in your assistant latency report.')
add('ablation-delta',['10-05','11-05'],'Measure an ablation honestly','Return full_score-ablated_score. Preserve the sign so a harmful component has a negative contribution. Scores use the same metric and held-out set.','double improvement(double full_score, double ablated_score)','Subtract ablated from full.\n    return 0.0;','    return full_score-ablated_score;',[
 ('Helpful component','near(improvement(.8,.6),.2)','The component adds 0.2 to the score.'),('Harmful component','near(improvement(.6,.8),-.2)','Do not take an absolute value.'),('No measured change','near(improvement(.7,.7),0)','A zero delta is still an informative result.')],['Metric direction matters: this function assumes higher is better.','Loss reduction would use a different sign convention.'],'A score difference is not causal evidence unless the runs control confounding changes. Raw counts and uncertainty still matter.','Run matched-budget baselines, freeze the evaluation set, and document one negative result.')
